  function chestEntityByKey(key){const entity=blockEntities[key];if(!entity)return null;if(entity.id===BLOCK.CHEST){if(!Array.isArray(entity.slots))entity.slots=Array(SINGLE_CHEST_SLOTS).fill(null);if(entity.slots.length<SINGLE_CHEST_SLOTS)entity.slots=entity.slots.concat(Array(SINGLE_CHEST_SLOTS-entity.slots.length).fill(null));if(entity.slots.length>SINGLE_CHEST_SLOTS)entity.slots=entity.slots.slice(0,SINGLE_CHEST_SLOTS);entity.partnerKey=typeof entity.partnerKey==='string'?entity.partnerKey:'';entity.doublePart=entity.doublePart==='right'?'right':(entity.doublePart==='left'?'left':'');entity.variant=entity.variant==='ender'?'ender':'normal';const d=Array.isArray(entity.dir)&&entity.dir.length===3?entity.dir:[0,0,1];entity.dir=Math.abs(Number(d[0]))>Math.abs(Number(d[2]))?[Number(d[0])>=0?1:-1,0,0]:[0,0,Number(d[2])>=0?1:-1];if(entity.partnerKey){const partner=blockEntities[entity.partnerKey];if(!(partner&&partner.id===BLOCK.CHEST&&partner.partnerKey===key)){entity.partnerKey='';entity.doublePart='';}}}return entity;}
