  function villagerWorkstationTarget(h,profession,home){const def=VILLAGER_PROFESSION_BY_ID.get(profession),site=h?.workstationSite;if(!def||def.workstation===BLOCK.AIR||!site)return null;const x=Math.round(Number(site.x)),y=Math.round(Number(site.y)),z=Math.round(Number(site.z));if(![x,y,z].every(Number.isFinite)||!insideActive(x,y,z))return null;const current=getBlock(x,y,z);if(current!==def.workstation)return null;return{x:x+.5,y,z:z+.5,blockX:x,blockY:y,blockZ:z,block:def.workstation};}
  function updateVillagerDoors(m,dt,target=null){m.doorCloseTimer=Math.max(0,(Number(m.doorCloseTimer)||0)-dt);if(m.openedDoorKey&&m.doorCloseTimer<=0){const [bx,by,bz]=m.openedDoorKey.split(',').map(Number);if([bx,by,bz].every(Number.isFinite)&&Math.hypot(m.x-(bx+.5),m.z-(bz+.5))>1.35){const e=doorSharedEntity(bx,by,bz);if(e)setDoorOpen(e,false);m.openedDoorKey='';}}if(!target)return;const dx=Number(target.x)-m.x,dz=Number(target.z)-m.z,l=Math.hypot(dx,dz);if(l<.05)return;const nx=dx/l,nz=dz/l;for(const reach of[.55,.9,1.2]){const x=Math.floor(m.x+nx*reach),z=Math.floor(m.z+nz*reach);for(const yy of[Math.floor(m.y),Math.floor(m.y+1)]){if(getBlock(x,yy,z)!==BLOCK.DOOR)continue;const base=doorBasePosition(x,yy,z),e=ensureDoorPair(base.x,base.y,base.z);if(e){setDoorOpen(e,true);m.openedDoorKey=deltaKey(base.x,base.y,base.z);m.doorCloseTimer=1.35;return;}}}}
  function updateVillager(m,dt){ensureVillagerTradeState(m);m.personalAnger=Math.max(0,(Number(m.personalAnger)||0)-dt/90);const phase=villagerSchedulePhase();m.schedule=phase;if(phase!=='sleep'&&m.sleeping)wakeVillager(m,'morning');if(phase==='sleep'){if(m.sleeping){m.moving=false;updateVillagerDoors(m,dt,null);return;}const bed=m.bed;updateVillagerDoors(m,dt,bed);if(bed&&moveMobTowardPoint(m,bed,dt,.62,.72)){m.sleeping=true;m.sleepBedKey=bed.baseKey||'';m.x=bed.x;m.z=bed.z;m.y=Number(bed.y)||m.y;m.moving=false;}else if(!bed)wander(m,dt);return;}if(phase==='work'){m.workstation=villagerWorkstationTarget(m.houseSpec,m.profession,m.home);const target=m.workstation||m.home;updateVillagerDoors(m,dt,target);const atWork=moveMobTowardPoint(m,target,dt,.67,1.05);if(atWork&&m.workstation)villagerWorkRestock(m,dt);return;}if(phase==='socialize'){const center=m.villageCenter||m.home;updateVillagerDoors(m,dt,center);moveMobTowardPoint(m,center,dt,.58,1.6);m.gossipTimer=(Number(m.gossipTimer)||0)-dt;if(m.gossipTimer<=0){spreadVillageGossip(m);m.gossipTimer=4+Math.random()*2;}return;}updateVillagerDoors(m,dt,m.home);if(!moveMobTowardPoint(m,m.home,dt,.55,.8))return;m.moving=false;}
  function golemAttackMob(golem,target){if(!target?.alive||target.hurt>0)return;target.health-=14;target.hurt=.2;const dx=target.x-golem.x,dz=target.z-golem.z,l=Math.hypot(dx,dz)||1;target.knockX=dx/l*7;target.knockZ=dz/l*7;target.vy=Math.max(Number(target.vy)||0,4.5);playMobCue(golem,'attack',.82);if(target.health<=0){target.health=0;target.dying=true;}}
  function nearestGolemEnemy(m){let best=null,bestD=18;for(const target of mobs){if(!target?.alive||target===m||target.dimension!==m.dimension||!isHostile(target)||target.boss)continue;const d=Math.hypot(target.x-m.x,target.z-m.z);if(d<bestD){best=target;bestD=d;}}return best;}
  function updateIronGolem(m,dt){const village=m.villageKey?villageStateForKey(m.villageKey):null,playerHostile=!!village&&(village.hostileFor>0||village.reputation<=-25),mobTarget=nearestGolemEnemy(m);let tx=null,tz=null,targetMob=null,targetPlayer=false;if(playerHostile&&Math.hypot(player.x-m.x,player.z-m.z)<20){tx=player.x;tz=player.z;targetPlayer=true;}else if(mobTarget){tx=mobTarget.x;tz=mobTarget.z;targetMob=mobTarget;}if(tx!=null){const dx=tx-m.x,dz=tz-m.z,dist=Math.hypot(dx,dz),yaw=smoothTurnMob(m,Math.atan2(dx,-dz),dt,5.4);if(dist>1.7)m.moving=moveMob(m,Math.sin(yaw)*m.speed*.92*dt,-Math.cos(yaw)*m.speed*.92*dt);if(dist<=2.0&&m.cooldown<=0){m.cooldown=1.05;if(targetPlayer)damagePlayer(7,'Iron Golem hit you!',m.x,m.z);else golemAttackMob(m,targetMob);}return;}if(m.home&&Math.hypot(m.x-m.home.x,m.z-m.home.z)>10){moveMobTowardPoint(m,m.home,dt,.52,2);return;}wander(m,dt);}

  function syncVillageResidents(){
    if(currentDimension!=='overworld')return;
    const villages=knownStructures.filter(s=>s?.type==='village'&&Array.isArray(s.houses));
    const valid=new Set(villages.map(villageKeyFor));
    mobs=mobs.filter(m=>!(m.villageResident||m.villageGolem)||valid.has(m.villageKey));
    for(const v of villages){
      const key=villageKeyFor(v),homes=v.houses.slice(0,15),offset=villageHash(key)%VILLAGER_PROFESSIONS.length;
      for(let i=0;i<homes.length;i++){
        const h=homes[i],residentKey=`${key}:villager:${i}`,bed=ensureVillageBed(h.bed),generatedProfessionIndex=Number.isInteger(Number(h.professionIndex))?clamp(Math.trunc(Number(h.professionIndex)),0,12):null,profession=VILLAGER_PROFESSIONS[generatedProfessionIndex??((offset+i)%VILLAGER_PROFESSIONS.length)].id;let m=mobs.find(q=>q.residentKey===residentKey);
        const persistent=villageStateForKey(key).residents[residentKey];
        if(!m){m=makeMob('villager',Number(h.x)||v.x,Number(h.z)||v.z,0,.68,20,{y:Number(h.y)||v.y+1,villageResident:true,villageKey:key,residentKey,profession:persistent?.profession||profession,home:{x:Number(h.x)||v.x,y:Number(h.y)||v.y+1,z:Number(h.z)||v.z},noRandomRespawn:true});mobs.push(m);}
        m.profession=m.profession||persistent?.profession||profession;m.home={x:Number(h.x)||v.x,y:Number(h.y)||v.y+1,z:Number(h.z)||v.z};m.villageCenter={x:Number(v.x)+.5,y:(Number(v.y)||m.home.y)+1,z:Number(v.z)+.5};m.bed=bed;m.houseSpec=h;m.workstation=villagerWorkstationTarget(h,m.profession,m.home);ensureVillagerTradeState(m);
      }
      const aliveVillagers=mobs.filter(q=>q.villageResident&&q.villageKey===key&&q.alive).length;let golem=mobs.find(q=>q.villageGolem&&q.villageKey===key);
      if(aliveVillagers>=3&&!golem){golem=makeMob('iron_golem',v.x+.5,v.z+.5,0,.58,100,{y:(v.y||8)+1,villageGolem:true,villageKey:key,home:{x:v.x+.5,y:(v.y||8)+1,z:v.z+.5},noRandomRespawn:true});mobs.push(golem);}
      if(golem){golem.villageKey=key;golem.home={x:v.x+.5,y:(v.y||8)+1,z:v.z+.5};if(!golem.alive&&aliveVillagers>=3&&golem.deadTimer<=0){Object.assign(golem,golem.home);golem.alive=true;golem.health=golem.maxHealth;golem.deathAnimating=false;}}
    }
  }
  function placeMobsNearPlayer(){
    syncVillageResidents();
    for(const m of mobs){
      if(m.dimension!==currentDimension)continue;
      if(m.villageResident||m.villageGolem){if(m.home){Object.assign(m,m.home);m.alive=true;m.health=Math.max(1,m.health||m.maxHealth);}continue;}
      if(m.boss){if(currentDimension==='end'){m.alive=true;m.y=34;}continue;}
      m.alive=false;m.deathAnimating=false;
      // Darkness no longer pops the whole hostile roster into existence in one frame.
      m.deadTimer=isHostile(m)?5+Math.random()*5:.15+Math.random()*.35;
      if(!isHostile(m))respawnMob(m);
    }
  }

