      refreshAtlasTransparency(images.atlas0);
      setupGL();
      loadSettings();
      loadCustomTitles();
      await loadCustomSkin();
      buildMenus();
      await initExtensionSystems();
      applyBitmapFont();
      // The title screen uses its panorama and does not need a generated voxel world.
      // World generation and mesh building now happen only after Continue/Create World.
      updateContinueInfo();
      updateLogo();
      updateModeUI();
      resize();
      loading.classList.remove('active');
      requestAnimationFrame(loop);
