    const boss=mobs.find(m=>m.boss&&m.alive&&mobEnabled(m));bossBar?.classList.toggle('hidden',!boss);if(boss&&bossHealthFill)bossHealthFill.style.width=`${clamp(boss.health/boss.maxHealth*100,0,100)}%`;
