  function facePlayerAndMove(m,dt,mult=1){const dist=Math.hypot(player.x-m.x,player.z-m.z);moveMobAlongPath(m,dt,mult);return dist;}
  function updateZombie(m,dt){const dist=Math.hypot(player.x-m.x,player.z-m.z),reachable=dist<14&&mobCanReachPlayer(m,16);if(reachable)facePlayerAndMove(m,dt);else wander(m,dt);if(reachable&&difficulty==='hard'&&gameRules.mobGriefing)tryZombieBreakDoor(m,dt);if(reachable&&mobCanMeleePlayer(m,1.45)&&m.cooldown<=0){m.cooldown=1.1;damagePlayer(2,'Zombie hit you!',m.x,m.z);}}
