  function mobPlayerDistance3D(m){return Math.hypot(player.x-m.x,(player.y+1)-(m.y+1),player.z-m.z);}
  function mobCanMeleePlayer(m,range=1.55){return mobPlayerDistance3D(m)<range&&canMobSeePlayer(m,range+1.1);}

  function mobBounds(m){
    if(m.type==='ender_dragon')return{min:[m.x-6.4,m.y,m.z-7.1],max:[m.x+6.4,m.y+4.6,m.z+7.1]};
    if(m.type==='ghast')return{min:[m.x-1,m.y,m.z-1],max:[m.x+1,m.y+2.6,m.z+1]};
    if(m.type==='iron_golem')return{min:[m.x-.72,m.y,m.z-.52],max:[m.x+.72,m.y+2.75,m.z+.52]};
    if(m.type==='enderman')return{min:[m.x-.34,m.y,m.z-.34],max:[m.x+.34,m.y+2.9,m.z+.34]};
    if(m.type==='spider'||m.type==='cave_spider')return{min:[m.x-.75,m.y,m.z-.75],max:[m.x+.75,m.y+1.0,m.z+.75]};
    if(m.type==='magma_cube'||m.type==='slime')return{min:[m.x-.75,m.y,m.z-.75],max:[m.x+.75,m.y+1.15,m.z+.75]};
    if(m.type==='cod'||m.type==='squid')return{min:[m.x-.42,m.y-.3,m.z-.42],max:[m.x+.42,m.y+.9,m.z+.42]};
    if(m.type==='chicken')return{min:[m.x-.28,m.y,m.z-.28],max:[m.x+.28,m.y+1.3,m.z+.28]};
    if(m.type==='cow'||m.type==='sheep')return{min:[m.x-.58,m.y,m.z-.78],max:[m.x+.58,m.y+1.6,m.z+.78]};
    return{min:[m.x-.34,m.y,m.z-.34],max:[m.x+.34,m.y+1.95,m.z+.34]};
  }
  function rayAABB(origin,dir,min,max,maxDist){let tmin=0,tmax=maxDist;for(let i=0;i<3;i++){if(Math.abs(dir[i])<1e-7){if(origin[i]<min[i]||origin[i]>max[i])return null;continue;}const inv=1/dir[i];let t1=(min[i]-origin[i])*inv,t2=(max[i]-origin[i])*inv;if(t1>t2)[t1,t2]=[t2,t1];tmin=Math.max(tmin,t1);tmax=Math.min(tmax,t2);if(tmax<tmin)return null;}return tmin;}
  function raycastMob(maxDist=7,ray=null){const origin=ray?.origin||getCameraBase(),dir=ray?.dir||getLookDir();let best=null;for(const m of mobs){if(!m.alive||!mobEnabled(m))continue;const b=mobBounds(m),dist=rayAABB(origin,dir,b.min,b.max,maxDist);if(dist!==null&&(!best||dist<best.dist))best={mob:m,dist};}return best;}
