  function generateEndCityEnchantedBook(entity,spec){if(!entity||spec?.loot!=='end_city'||!Array.isArray(entity.slots))return false;const chance=hash2(spec.x*47+11,spec.z*53-7,worldSeed+spec.y*31+2201);if(chance>.32)return false;const ids=Object.keys(ENCHANTMENTS),pick=ids[Math.floor(hash2(spec.x+71,spec.z-43,worldSeed+2213)*ids.length)%ids.length],def=ENCHANTMENTS[pick],level=clamp(1+Math.floor(hash2(spec.x-19,spec.z+97,worldSeed+2221)*Math.max(1,def.max)),1,def.max),book=makeEnchantedBook(pick,level);if(!book)return false;let slot=Math.floor(hash2(spec.x+29,spec.z+61,worldSeed+2237)*27);for(let tries=0;tries<27&&entity.slots[slot];tries++)slot=(slot+5)%27;if(entity.slots[slot])return false;entity.slots[slot]=book;return true;}
