  const PRINT_COLORS=Object.freeze({white:'#ffffff',black:'#111111',gray:'#aaaaaa',grey:'#aaaaaa',red:'#ff5555',orange:'#ff9f43',yellow:'#ffff55',green:'#55ff55',lime:'#aaff55',cyan:'#55ffff',blue:'#5599ff',navy:'#5555aa',purple:'#aa55ff',magenta:'#ff55ff',pink:'#ff88cc',gold:'#ffaa00'});
