    if(target.kind==='block'&&target.hit){const p=target.hit.prev;x=p[0]+.5;y=p[1];z=p[2]+.5;}
    else if(target.kind==='mob'&&target.mob){const d=getLookDir();x=target.mob.x-d[0]*.9;y=target.mob.y;z=target.mob.z-d[2]*.9;}
