      if(!context.commandBlock&&!isLocalOP())throw new Error('OP rank is required to use commands.');
      if(name==='help')output='Commands: print, printcolor, printcolorspesific, printtitle, tp, give, summon, gamemode, time, weather, setblock, effect, gamerule, locate, dimension, kill';
      else if(name==='print'||name==='say'){const message=args.join(' ')||'...';sendPlainChat(message);output=context.commandBlock?`Printed: ${message}`:'';}
      else if(name==='printcolor'){const colorName=String(args.shift()||'').toLowerCase(),color=PRINT_COLORS[colorName];if(!color)throw new Error(`Unknown color. Try: ${Object.keys(PRINT_COLORS).filter((v,i,a)=>a.indexOf(v)===i).join(', ')}`);const message=args.join(' ')||'...';sendPlainChat(message,color);output=context.commandBlock?`Printed ${colorName}: ${message}`:'';}
      else if(name==='printcolorspesific'||name==='printcolorspecific'){const color=String(args.shift()||'');if(!/^#[0-9a-f]{3,8}$/i.test(color))throw new Error('Use a color ID such as #55ff55');const message=args.join(' ')||'...';sendPlainChat(message,color);output=context.commandBlock?`Printed ${color}: ${message}`:'';}
      else if(name==='printtitle'){const target=args.shift();const message=args.join(' ');if(!target||!message)throw new Error('Use: printtitle person|everyone message');if(String(target).toLowerCase()==='everyone'||targetMatchesLocal(target))showScreenTitle(message);const found=remoteByName(target);if(netSession?.connected&&(String(target).toLowerCase()==='everyone'||found))netSession.send('admin_title',{target,targetId:found?.[0]||'',message});if(String(target).toLowerCase()!=='everyone'&&!targetMatchesLocal(target)&&!found)throw new Error(`Player “${target}” was not found`);output=`Title sent to ${target}`;}
      else if(name==='give'){
        let count=1;if(args.length&&Number.isFinite(Number(args.at(-1))))count=clamp(Math.floor(Number(args.pop())||1),1,STACK_MAX*36);if(args[0]==='@s')args.shift();const entry=findContent(args.join(' '));if(!entry)throw new Error('Unknown item');let left=count;while(left>0){const batch=Math.min(left,STACK_MAX),rem=addInventory(entry.id,batch);left-=batch-rem;if(rem===batch)break;}updateHotbar();output=`Gave ${count-left} ${entry.name}`;
      }
