  function setRemoteRank(id,rank){if(netSession?.role!=='host'||!['OP','Player','Visitor'].includes(rank))return;playerRanks[id]=rank;const p=remotePlayers.get(id);if(p){p.rank=rank;playerRanks[`name:${String(p.name||'Player').toLowerCase()}`]=rank;}netSession.send('rank',{targetId:id,rank});saveWorld();updatePausePlayers();}
