    const own=document.createElement('div');own.className='pausePlayerRow';own.innerHTML=`<b>${escapeHTML(localPlayerName())} <small>(You)</small></b><span class="rankBadge rank${localRank}">${escapeHTML(localRank)}${netSession?.role==='host'||!netSession?.connected?' • Owner':''}</span>`;pausePlayerList.appendChild(own);
    for(const[id,p]of remotePlayers){const row=document.createElement('div'),rank=rankForRemote(id);row.className='pausePlayerRow';const who=document.createElement('b');who.textContent=p.name||'Player';if(netSession?.role==='host'){const button=document.createElement('button');button.className=`rankButton rank${rank}`;button.textContent=rank;button.title='Owner: click to change this player rank';button.onclick=()=>cycleRemoteRank(id);row.append(who,button);}else{const badge=document.createElement('span');badge.className=`rankBadge rank${rank}`;badge.textContent=rank;row.append(who,badge);}pausePlayerList.appendChild(row);}
