  function networkPacket(packet){
    const data=packet.data||{};
    if(packet.type==='player'){const old=remotePlayers.get(packet.sender)||{};remotePlayers.set(packet.sender,{...old,...data,name:packet.name,rank:rankForRemote(packet.sender),seen:Date.now()});return;}
    if(packet.type==='hello'){if(!(packet.sender in playerRanks))playerRanks[packet.sender]=netSession?.role==='guest'?'OP':(playerRanks[`name:${String(packet.name||'Player').toLowerCase()}`]||'Player');remotePlayers.set(packet.sender,{name:packet.name,rank:rankForRemote(packet.sender),dimension:currentDimension,x:player.x,y:player.y,z:player.z,yaw:0,phase:0,moving:false,seen:Date.now()});if(netSession?.role==='host'){netSession.send('rank',{targetId:packet.sender,rank:rankForRemote(packet.sender)});netSession.sendLarge('world',networkWorldSnapshot());}updatePausePlayers();return;}
    if(packet.type==='rank'){if(data.targetId===netSession?.id&&['OP','Player','Visitor'].includes(data.rank)){localRank=data.rank;showToast(`Your rank is now ${localRank}`);updatePausePlayers();}return;}
    if(packet.type==='block'){if(netSession?.role==='host'&&rankForRemote(packet.sender)==='Visitor')return;if(data.dimension===currentDimension&&insideActive(data.x,data.y,data.z)){applyingNetworkBlock=true;setBlock(Number(data.x),Number(data.y),Number(data.z),Number(data.v));applyingNetworkBlock=false;}return;}
    if(packet.type==='chat'){addChatMessage(data.text,!!data.system,{plain:!!data.plain,color:data.color||'',speaker:packet.name});return;}
    if(packet.type==='admin_title'){if(!commandCanControlTarget(packet.sender))return;const target=String(data.target||'').toLowerCase();if(data.targetId===netSession?.id||target==='everyone'||targetMatchesLocal(target))showScreenTitle(data.message,data.color||'#fff');return;}
    if(packet.type==='admin_teleport'){if(!commandCanControlTarget(packet.sender))return;const target=String(data.target||'').toLowerCase();if(data.targetId===netSession?.id||target==='everyone'||targetMatchesLocal(target))teleportLocal(Number(data.x),Number(data.y),Number(data.z));return;}
    if(packet.type==='admin_kill'){if(!commandCanControlTarget(packet.sender))return;const target=String(data.target||'').toLowerCase();if(data.targetId===netSession?.id||targetMatchesLocal(target))commandKillLocalPlayer('Killed by command');return;}
    if(packet.type==='world'&&netSession?.role==='guest')applyNetworkWorld(data);
  }
