  async function applyNetworkWorld(data){strippedSavedFlowKeys.clear();if(loadingWorld||!data?.dimension)return;try{worldSeed=Number(data.seed)||worldSeed;worldType=['classic','flat','infinite'].includes(data.worldType)?data.worldType:worldType;gameMode=data.mode==='survival'?'survival':'creative';difficulty=DIFFICULTIES.includes(data.difficulty)?data.difficulty:difficulty;worldClock=Number(data.clock)||worldClock;if(data.endProgress)endProgress={...endProgress,...data.endProgress};const targetDimension=['overworld','nether','end'].includes(data.currentDimension)?data.currentDimension:currentDimension;dimensionStates[targetDimension]=data.dimension;currentDimension=targetDimension;const s=data.dimension,hostX=Number(s.player?.x),hostY=Number(s.player?.y),hostZ=Number(s.player?.z);let result;if(worldType==='infinite'){infiniteDeltas=Object.create(null);for(const row of s.deltas||[]){const value=Number(row[3])||0,key=deltaKey(row[0],row[1],row[2]);if(BLOCK_BY_ID.get(value)?.flowing)strippedSavedFlowKeys.add(key);else infiniteDeltas[key]=value;}result=await runWorldWorker('infinite',{seed:worldSeed,centerChunkX:Number.isFinite(hostX)?Math.floor(hostX/CHUNK_SIZE):0,centerChunkZ:Number.isFinite(hostZ)?Math.floor(hostZ/CHUNK_SIZE):0,radius:Math.min(renderDistance,3),deltas:Object.entries(infiniteDeltas).map(([key,v])=>[...key.split(',').map(Number),Number(v)])});}else{worldW=s.worldW||WORLD_W;worldD=s.worldD||WORLD_D;worldOriginX=Number(s.originX)||0;worldOriginZ=Number(s.originZ)||0;world=rleDecode(s.blocks,worldW*WORLD_H*worldD);stripSavedFlowingFluids(world);result=await runWorldWorker('mesh',{worldBuffer:world.slice().buffer,worldType,worldW,worldD,originX:worldOriginX,originZ:worldOriginZ});}applyWorkerWorld(result,false);restoreDimensionMetadata(s);hydrateEntityBlocks(result.entityBlocksBuffer||result.entityBlocks);if([hostX,hostY,hostZ].every(Number.isFinite)){player.x=hostX+1.25;player.y=hostY;player.z=hostZ;player.vy=0;}resetMobs();placeMobsNearPlayer();updateModeUI();showToast('Host world synchronized');}catch(error){console.warn(error);showToast('World synchronization failed');}}

  function spawnEffect(kind,x,y,z){if(kind==='crit'){particles.push({kind,frame:9,x,y,z,age:0,duration:.45,size:.75});return;}const count=kind==='explosion'?5:1;for(let i=0;i<count;i++)particles.push({kind,frame:0,x:x+(hash2(i,1,worldSeed)-.5)*.7,y:y+(hash2(i,2,worldSeed)-.5)*.6,z:z+(hash2(i,3,worldSeed)-.5)*.7,age:0,duration:kind==='explosion'?.8:.65,size:kind==='explosion'?1.35:.85});}
  const MAX_BLOCK_PARTICLES=180;
  function trimParticleBudget(){if(particles.length<=MAX_BLOCK_PARTICLES)return;particles.splice(0,particles.length-MAX_BLOCK_PARTICLES);}
  function spawnBlockParticles(blockId,x,y,z,mode='break'){
    if(blockId===BLOCK.AIR||isFluid(blockId)||BLOCK_BY_ID.get(blockId)?.entityOnly)return;
    const count=mode==='step'?2:12,topMode=mode==='step',baseSize=mode==='step'?.105:.145;
    for(let i=0;i<count;i++){
      const tile=blockTile(blockId,topMode?'top':(i%3===0?'top':'side'),x,z),uv=tileUV(tile),angle=Math.random()*Math.PI*2,speed=mode==='step'?.22:.65+Math.random()*.85;
      particles.push({kind:'block_fragment',uv,x:x+(Math.random()-.5)*(mode==='step'?.42:.72),y:y+(mode==='step'?.025:(Math.random()-.5)*.65),z:z+(Math.random()-.5)*(mode==='step'?.42:.72),vx:Math.cos(angle)*speed,vy:mode==='step'?.16+Math.random()*.18:.8+Math.random()*1.7,vz:Math.sin(angle)*speed,gravity:mode==='step'?2.2:5.8,age:0,duration:mode==='step'?.42:.72,size:baseSize*(.75+Math.random()*.65)});
    }
    trimParticleBudget();
  }
  function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.age+=dt;if(p.age>=p.duration){particles.splice(i,1);continue;}if(p.kind==='block_fragment'){p.x+=(p.vx||0)*dt;p.y+=(p.vy||0)*dt;p.z+=(p.vz||0)*dt;p.vy=(p.vy||0)-(p.gravity||5)*dt;continue;}if(p.kind!=='crit')p.frame=clamp(Math.floor(p.age/p.duration*8),0,7);p.y+=dt*.18;}}

