  function drawChests(mvp,camPos){
    const singleData=[],largeData=[];
    for(const [key,e0] of cachedBlockEntityEntries()){
      if(e0?.id!==BLOCK.CHEST)continue;
      const [x,y,z]=key.split(',').map(Number);
      if(!insideActive(x,y,z)||getBlock(x,y,z)!==BLOCK.CHEST)continue;
      const e=chestEntityByKey(key)||e0,dir=e.dir||[0,0,1],yaw=chestYawForDir(dir);
      if(chestIsDouble(e)){
        if(e.doublePart!=='left')continue;
        const partnerKey=e.partnerKey,partner=chestEntityByKey(partnerKey);
        if(!partner)continue;
        const [px,py,pz]=partnerKey.split(',').map(Number);
        buildChestEntityModel(largeData,[(x+px)/2+.5,(y+py)/2+7/16,(z+pz)/2+.5],1,yaw,0,0,true);
      }else{
        buildChestEntityModel(singleData,[x+.5,y+7/16,z+.5],1,yaw,0,0,false);
      }
    }
    if(singleData.length)drawDynamic(singleData,entityBuffer,chestEntityTexture||terrainTexture,mvp,camPos,1,1,0);
    if(largeData.length)drawDynamic(largeData,entityBuffer,largeChestEntityTexture||chestEntityTexture||terrainTexture,mvp,camPos,1,1,0);
  }
  
