  function setHeldBlockFaces(element,content){
    const topTile=content.top||content.all||content.side;
    const sideTile=content.side||content.all||content.top;
    const topFace=element.querySelector('.heldTop'),frontFace=element.querySelector('.heldFront'),rightFace=element.querySelector('.heldRight');
    if(topFace)topFace.style.backgroundPosition=`${-topTile[0]*76}px ${-topTile[1]*76}px`;
    if(frontFace)frontFace.style.backgroundPosition=`${-sideTile[0]*76}px ${-sideTile[1]*76}px`;
    if(rightFace)rightFace.style.backgroundPosition=`${-sideTile[0]*76}px ${-sideTile[1]*76}px`;
  }

  function updateHeldView(){
    if(!firstPersonHeld)return;
    const visible=state==='playing'&&!thirdPerson;
    firstPersonHeld.classList.toggle('hidden',!visible);
    if(!visible){firstPersonOffhand?.classList.add('hidden');return;}

    const content=selectedContent();
    heldArm3D?.classList.toggle('alexaArm',activePlayerModelKey()==='alexa');
    heldArm3D?.classList.toggle('hidden',!!content);
    heldBlock.classList.add('hidden');heldItem.classList.add('hidden');
    if(content){
      if(BLOCK_BY_ID.has(content.id)){heldBlock.classList.remove('hidden');setHeldBlockFaces(heldBlock,content);}
      else{heldItem.classList.remove('hidden');heldItem.style.backgroundPosition=`${-content.itemX*112}px ${-content.itemY*112}px`;}
    }

    const offContent=CONTENT_BY_ID.get(offhandId)||null;
    firstPersonOffhand?.classList.toggle('hidden',!offContent);
    offhandHeldBlock?.classList.add('hidden');offhandHeldItem?.classList.add('hidden');
    if(offContent){
      if(BLOCK_BY_ID.has(offContent.id)){offhandHeldBlock.classList.remove('hidden');setHeldBlockFaces(offhandHeldBlock,offContent);}
      else{offhandHeldItem.classList.remove('hidden');offhandHeldItem.style.backgroundPosition=`${-offContent.itemX*112}px ${-offContent.itemY*112}px`;}
    }

    const walk=player.moving&&player.grounded?1:0;
    const bobX=Math.sin(player.walkTime)*8*walk;
    const bobY=Math.abs(Math.cos(player.walkTime))*6*walk;
    const swingAmount=handSwingAmount();
    const swingY=swingAmount*76,swingRot=swingAmount*22;
    const heldScale=inputMode==='touch'?.72:1;
    firstPersonHeld.style.transform=`translate3d(${bobX}px,${bobY+swingY}px,0) rotate(${swingRot}deg) scale(${heldScale})`;
    if(firstPersonOffhand)firstPersonOffhand.style.transform=`translate3d(${-bobX*.55}px,${bobY*.65}px,0) scale(${inputMode==='touch'?.68:1})`;
  }
