  function createNewCharacterLook(){creatingCharacter=true;editingCharacterId=null;pendingCustomSkinData='';customSkinModel='classic';if(customSkinFile)customSkinFile.value='';renderCharacterCarousel();updateCharacterEditor(null);characterCarousel?.scrollTo({left:characterCarousel.scrollWidth,behavior:'smooth'});showToast('New character look');}
