    for(const [box,head] of [[playerPreview,previewHead],[$('titlePlayerPreview'),titlePreviewHead],[$('characterPagePreview'),characterPageHead]]){if(!box||!head)continue;const r=box.getBoundingClientRect(),x=clamp((event.clientX-(r.left+r.width/2))/(r.width/2),-1,1),y=clamp((event.clientY-(r.top+r.height/2))/(r.height/2),-1,1);head.style.transform=`rotateY(${x*24}deg) rotateX(${-y*18}deg)`;}
