      bitmapObserver=new MutationObserver(records=>{if(bitmapMutating)return;for(const record of records){const el=record.target.nodeType===1?record.target:record.target.parentElement;if(!el)continue;const candidate=el.matches?.('.pixelButton,.menuHeader h2,.dialog h2')?el:el.closest?.('.pixelButton,.menuHeader h2,.dialog h2');if(candidate&&!candidate.querySelector('.bitmapGlyph'))bitmapizePlainElement(candidate);}});
