    BLOCKS.forEach(b=>{const iconFace=b.id===BLOCK.CHEST&&b.front?b.front:(b.all||b.top||b.side);b.iconX=iconFace[0];b.iconY=iconFace[1];});

    rebuildHotbarSlots(true);

    const inv=$('inventoryGrid');inv.innerHTML='';
