      const cell=document.createElement('button');
      cell.className='inventorySlot inventoryCell empty';cell.dataset.index=String(i);
      cell.onclick=e=>moveStackSlot(i,false,!!e.ctrlKey);
      cell.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();moveStackSlot(i,true,false);return false;};
      inv.appendChild(cell);
