      const cell=document.createElement('button');cell.className='inventorySlot inventoryCell empty';cell.dataset.hotbar=String(i);
      cell.onclick=e=>{selectedSlot=i;moveStackSlot(36+i,false,!!e.ctrlKey);};
      cell.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();selectedSlot=i;moveStackSlot(36+i,true,false);return false;};
      inventoryHotbarGrid.appendChild(cell);
