  function rleEncode(arr){let out=[],v=arr[0],n=1;for(let i=1;i<arr.length;i++){if(arr[i]===v&&n<65535)n++;else{out.push(v.toString(36)+'.'+n.toString(36));v=arr[i];n=1;}}out.push(v.toString(36)+'.'+n.toString(36));return out.join(',');}
  function rleDecode(s,len){const out=new Uint8Array(len);let p=0;for(const pair of String(s||'').split(',')){if(!pair)continue;const[v,n]=pair.split('.').map(x=>parseInt(x,36));if(!Number.isFinite(v)||!Number.isFinite(n)||n<1||p+n>len)throw new Error('Invalid saved world data');out.fill(v,p,p+n);p+=n;}if(p!==len)throw new Error('Save size mismatch');return out;}
  function expandLegacyWorld(oldWorld,oldHeight,w=worldW,d=worldD){const expanded=new Uint8Array(w*WORLD_H*d),layer=w*d;for(let y=0;y<Math.min(oldHeight,WORLD_H);y++)expanded.set(oldWorld.subarray(y*layer,(y+1)*layer),y*layer);return expanded;}
  function shiftCoordKeyY(key,dy){const p=String(key||'').split(',').map(Number);return p.length===3&&p.every(Number.isFinite)?deltaKey(p[0],p[1]+dy,p[2]):key;}
  function shiftStructureY(value,dy){if(Array.isArray(value))return value.map(v=>shiftStructureY(v,dy));if(!value||typeof value!=='object')return value;const out={};for(const[k,v]of Object.entries(value)){if((k==='y'||k==='doorY'||k==='baseY')&&Number.isFinite(Number(v)))out[k]=Number(v)+dy;else out[k]=shiftStructureY(v,dy);}return out;}
  function shiftLegacyInfiniteOverworldSnapshot(source,dy){if(!source||typeof source!=='object')return source;const out=JSON.parse(JSON.stringify(source));out.worldHeight=WORLD_H;if(out.player&&Number.isFinite(Number(out.player.y)))out.player.y=Number(out.player.y)+dy;if(Array.isArray(out.deltas))out.deltas=out.deltas.map(row=>Array.isArray(row)&&row.length>=4?[Number(row[0]),Number(row[1])+dy,Number(row[2]),Number(row[3])]:row);if(Array.isArray(out.openDoors))out.openDoors=out.openDoors.map(key=>shiftCoordKeyY(key,dy));if(Array.isArray(out.editedBlocks))out.editedBlocks=out.editedBlocks.map(key=>shiftCoordKeyY(key,dy));if(out.blockEntities&&typeof out.blockEntities==='object'){const shifted={};for(const[key,e]of Object.entries(out.blockEntities)){const copy=e&&typeof e==='object'?{...e}:e;if(copy?.baseKey)copy.baseKey=shiftCoordKeyY(copy.baseKey,dy);shifted[shiftCoordKeyY(key,dy)]=copy;}out.blockEntities=shifted;}if(Array.isArray(out.boats))out.boats=out.boats.map(b=>({...b,y:Number(b.y||0)+dy}));if(Array.isArray(out.minecarts))out.minecarts=out.minecarts.map(c=>({...c,y:Number(c.y||0)+dy}));if(Array.isArray(out.structures))out.structures=shiftStructureY(out.structures,dy);return out;}
