  function renderLocalGameScan(games){
    if(!localGameList)return;localGameList.innerHTML='';
    const rows=[...games.values()].sort((a,b)=>b.seenAt-a.seenAt);
    if(!rows.length){localGameList.innerHTML='<p class="smallText">Searching… local games will appear here.</p>';return;}
    for(const game of rows){const row=document.createElement('div');row.className='localGameRow';const info=document.createElement('span'),button=document.createElement('button');info.innerHTML=`<b>${escapeHTML(game.name||'DorukCraft World')}</b><small>Host: ${escapeHTML(game.host||'Player')}</small>`;button.className='pixelButton compact primary';button.textContent='Join';button.onclick=()=>{try{netSession.name=(multiplayerName.value.trim()||'Player').slice(0,24);netSession.joinLocalGame(game.room);showToast(`Joining ${game.name||'local game'}`);}catch(error){multiplayerStatus.textContent=error.message;}};row.append(info,button);localGameList.appendChild(row);}
  }
  function scanForLocalGames(){
    if(!netSession)return;const games=new Map();renderLocalGameScan(games);
    try{netSession.name=(multiplayerName.value.trim()||'Player').slice(0,24);netSession.scanLocalGames(game=>{games.set(game.room,game);renderLocalGameScan(games);});setTimeout(()=>{if(!games.size&&localGameList)localGameList.innerHTML='<p class="smallText">No discoverable local games found. You can host one, or use Advanced Connection for another device.</p>';},4400);}catch(error){multiplayerStatus.textContent=error.message;}
  }
