  async function openSavedWorld(id){
    if(!id)return;
    saveWorld('leaving');
    let selected=true;
    if(window.DorukCraftPersistence?.prepareWorld)selected=await window.DorukCraftPersistence.prepareWorld(id);
    else if(window.DorukCraftPersistence)selected=window.DorukCraftPersistence.selectWorld(id);
    if(!selected){showToast('That world save could not be read');return;}
    currentWorldId=id;startGame(true);
  }
  function deleteSavedWorld(id,name){
    if(!id)return;
    if(!confirm(`Delete "${name||'this world'}"? This cannot be undone.`))return;
    window.DorukCraftPersistence?.deleteWorld?.(id);
    if(currentWorldId===id)currentWorldId=window.DorukCraftPersistence?.getActiveWorldId?.()||null;
    updateContinueInfo();showToast('World deleted');
  }
  function updateContinueInfo(){
    const worlds=window.DorukCraftPersistence?.listWorldsSync?.()||[];
    const active=window.DorukCraftPersistence?.getActiveWorldId?.()||worlds[0]?.id||null;
    currentWorldId=currentWorldId&&worlds.some(w=>w.id===currentWorldId)?currentWorldId:active;
    if(!worldListEl)return;
    worldListEl.innerHTML='';
    if(!worlds.length){
      const empty=document.createElement('button');empty.id='continueBtn';empty.className='worldRow';empty.disabled=true;empty.innerHTML='<img src="./assets/images/95a893d1a23205f1f08f.png" alt="World preview"><span class="worldRowText"><b>My World</b><small>No world saved yet — press New</small></span><span class="worldRowAction">＋</span>';worldListEl.appendChild(empty);return;
    }
    for(const meta of worlds){
      const wrap=document.createElement('div');wrap.className='worldRowWrap';
      const row=document.createElement('button');row.className='worldRow';row.dataset.worldId=meta.id;
      const mode=meta.mode==='survival'?'Survival':'Creative',type=meta.worldType==='flat'?'Flat':meta.worldType==='infinite'?'Infinite':'Old';
      const saved=meta.savedAt?new Date(meta.savedAt).toLocaleString():'';
      row.innerHTML=`<img src="./assets/images/95a893d1a23205f1f08f.png" alt="World preview"><span class="worldRowText"><b>${escapeHTML(meta.name||'My World')}</b><small>${mode} • ${type}${saved?` • ${escapeHTML(saved)}`:''}${meta.id===active?' • Current':''}</small></span><span class="worldRowAction">▶</span>`;
      row.onclick=()=>openSavedWorld(meta.id);
      const del=document.createElement('button');del.className='worldDeleteButton';del.type='button';del.title=`Delete ${meta.name||'world'}`;del.setAttribute('aria-label',del.title);del.textContent='×';del.onclick=e=>{e.stopPropagation();deleteSavedWorld(meta.id,meta.name);};
      wrap.append(row,del);worldListEl.appendChild(wrap);
    }
  }

