    const ps=family==='playstation';
    const a=$('controllerFaceA'),x=$('controllerFaceX'),y=$('controllerFaceY'),b=$('controllerFaceB'),hint=$('controllerTriggerHint');
    if(a)a.innerHTML=ps?'<span class="ps4ButtonIcon cross"></span>':'A';
    if(x)x.innerHTML=ps?'<span class="ps4ButtonIcon square"></span>':'X';
    if(y)y.innerHTML=ps?'<span class="ps4ButtonIcon triangle"></span>':'Y';
