  function smartInputTap(ray=null){
    if(state!=='playing')return;const target=sightTarget(7,ray),hit=target?.kind==='block'?target.hit:null,def=hit&&BLOCK_BY_ID.get(hit.b);
    if(target?.kind==='mob'){performPlayerAttack(target.mob);return;}
    if(target?.kind==='boat'){mountBoat(target.boat);return;}
    if(target?.kind==='minecart'){mountMinecart(target.minecart);return;}
    if(hit&&(def?.interactable||[BLOCK.DOOR,BLOCK.CRAFTING_TABLE,BLOCK.FURNACE,BLOCK.TNT,BLOCK.END_PORTAL_FRAME].includes(hit.b))&&interactBlock(hit))return;
    beginUseAction(ray);if(rightUseHeld)endUseAction();
  }

